function store(){const c=context();if(!c.chatId)throw Error('请先打开聊天');return c.chatMetadata[NS]??=newStore();}
function persistSession(){if(restoring||clearInProgress||!context().chatId)return;try{saveSession(chatKey(),{draft,draftVersions,pendingDrafts,batchQueue,batchTotal,batchLedger,batchPaused:true,autoPaused,revision:store().revision});}catch(e){notify('本地任务恢复状态保存失败：'+e.message,true);}}
function restoreSession(){if(!context().chatId)return;restoring=true;try{const v=loadSession(chatKey());if(v&&v.revision>=Number(store().clearedAtRevision||0)){draft=v.draft?.chat===chatKey()?v.draft:null;draftVersions=(v.draftVersions||[]).filter(d=>d.chat===chatKey());pendingDrafts=(v.pendingDrafts||[]).filter(x=>x.draft?.chat===chatKey()&&!store().batches.some(b=>(b.ids||[]).some(id=>x.draft.items.some(m=>m.id===id))));batchQueue=v.batchQueue||[];batchTotal=v.batchTotal||0;batchLedger=v.batchLedger||[];batchPaused=true;autoPaused=v.autoPaused||false;
 for(const recovered of [draft,...draftVersions,...pendingDrafts.flatMap(e=>[e.draft,...e.versions||[]])].filter(Boolean))if(recovered.checking){recovered.checking=false;recovered.checkInterrupted=true;}
 if(draft&&!draft.savedReview&&store().batches.some(b=>(b.ids||[]).some(id=>draft.items.some(m=>m.id===id)))){draft=null;draftVersions=[];}
 for(const row of batchLedger)if(row.status==='running')row.status='paused';
 }}finally{restoring=false;}restorePendingDraft();}
function readCount(){const mode=panel?.querySelector('[data-count-mode]'),value=panel?.querySelector('[data-count-value]');if(!mode)return;settings.memoryCountMode=mode.value;const active=mode.value==='count';value.closest('label').hidden=!active;value.disabled=!active;if(!active)return;const count=Number(value.value);if(!Number.isInteger(count)||count<1||count>100)throw Error('记忆条数需为1～100');settings.memoryCount=count;}
function batchReport(){if(!batchLedger.length||!batchQueue.length&&!batchRunning)return '';const counts={};for(const b of batchLedger)counts[b.status]=(counts[b.status]||0)+1;const labels={saved:'已保存',draft:'待确认',failed:'失败',skipped:'跳过',pending:'未开始',running:'执行中',paused:'已暂停'};return '<section class="smm-content smm-batch-report"><b>批量任务 · '+batchTotal+'批</b><p>'+Object.entries(counts).map(([k,n])=>(labels[k]||k)+' '+n).join(' · ')+'</p>'+batchLedger.map(b=>'<small>第'+b.ordinal+'/'+batchTotal+'批 · 第'+b.start+'-'+b.end+'楼 · '+(labels[b.status]||b.status)+'</small>').join('<br>')+'</section>';}
function attic(){return settings.attics[characterKey()]??={memories:[]};}
function all(){let shared=[];try{shared=attic().memories;}catch{}const local=store().memories;return [...local,...shared.filter(m=>!local.some(x=>x.status==='active'&&(x.sharedId===m.id||m.copyOf===x.id)))];}
