function stashBatchDraft(){if(draft){pendingDrafts.push({draft:structuredClone(draft),versions:structuredClone(draftVersions)});draft=null;draftVersions=[];persistSession();}}
function queueGenerated(generated){if(draft?.versionId===generated.versionId||pendingDrafts.some(e=>e.draft.versionId===generated.versionId)){persistSession();return;}if(!draft&&!committing){draft=generated;draftVersions=[];tab='draft';open();}else pendingDrafts.push({draft:generated,versions:[]});persistSession();}
function restorePendingDraft(){if(!draft&&pendingDrafts.length){const entry=pendingDrafts.shift();draft=entry.draft;draftVersions=entry.versions||[];}}
function pendingDraftsView(){return pendingDrafts.length?'<section class="smm-content"><b>待确认草稿 · '+(pendingDrafts.length+(draft?1:0))+'份</b><p>各任务的草稿独立保存。</p>'+pendingDrafts.map((e,i)=>btn('pending-select','查看 '+h(e.draft.rangeLabel||floorLabel(e.draft.floors)),`data-index="${i}"`)).join('')+'</section>':'';}
