async function saveGenerated(generated){
 await saveCompletion;
 if(generated.chat!==chatKey()||clearInProgress||committing||generated.checking)return;
 if(draft===generated){await approve();return;}
 const index=pendingDrafts.findIndex(entry=>entry.draft===generated);
 if(index<0)return;
 const previous=draft,versions=draftVersions;
 if(previous?.checking||previous?.regenerating)return;
 const entry=pendingDrafts.splice(index,1)[0];
 if(previous)pendingDrafts.unshift({draft:previous,versions});
 draft=generated;draftVersions=entry.versions||[];
 try{await approve();}finally{
  if(draft===generated&&previous&&pendingDrafts[0]?.draft===previous){
   pendingDrafts.shift();
   pendingDrafts.push(entry);
   draft=previous;draftVersions=versions;
   if(generated.chat===chatKey()&&!clearInProgress)await render();
  }
 }
}
async function approve(){for(const el of panel?.querySelectorAll('[data-status-update]')||[]){const p=draft?.statusUpdates?.[Number(el.dataset.statusUpdate)];if(p)p.selected=el.checked;}if(committing)throw Error('正在保存，请勿重复确认');committing=true;saveCompletion=new Promise(resolve=>{releaseSave=resolve;});try{return await approveInternal();}finally{committing=false;releaseSave?.();releaseSave=null;activeLogTask=null;if(!draft&&pendingDrafts.length){restorePendingDraft();void render().catch(report);}if(!draft&&!pendingDrafts.length&&!job&&!batchQueue.length&&!batchRunning){if(!automaticTask)setTimeout(()=>maybeAutoMerge().then(()=>runAutomatic()).catch(report),0);}}}
