async function regenerate(){
 const previous=draft;
 const origin=chatKey();
 if(!previous)throw Error('没有草稿');
 const mode=await choiceDialog('重新生成',[['fresh','不参考检查意见，重新总结原材料'],['review','按AI检查意见重新总结'],['own','按我的意见重新总结']]);
 if(!mode)return;
 let userInstruction='';
 if(mode!=='fresh'){
  const input=mode==='review'
   ?await textDialog('补充你的意见','可以修改 AI 的建议或追加要求。与 AI 意见冲突时以你的输入为准。留空也可继续。','','开始生成')
   :await textDialog('按我的意见重新总结','填写这次希望如何调整；仍按原材料核对事实','','开始生成');
  if(input===null||mode==='own'&&!input.trim())return;
  userInstruction=input.trim();
 }
 if(chatKey()!==origin||draft!==previous)throw Error('聊天或草稿已改变，请重新操作');
 if(previous.savedReview&&(!previous.sources.length||scope==='attic'||previous.items.some(m=>m.imported)))throw Error('此记忆缺少可重写的当前聊天原文，可以手动编辑');
 const parentIds=new Set(previous.parents);
 const parents=parentIds.size?store().memories.filter(m=>parentIds.has(m.id)):null;
 if(parents&&parents.length!==parentIds.size)throw Error('部分整理来源已删除，请重新选择材料');
 const review=previous.checked?{issues:previous.issues,checkRaw:previous.checkRaw}:previous.reviewHistory;
 const instruction={userInstruction,reviewNotes:mode==='review'?compactReviewNotes(review?.issues):[]};
 const selected=previous.items[0]?.selectedFloors?.length?previous.items[0].selectedFloors:previous.floors;
 const start=selected.reduce((min,f)=>Math.min(min,f),Infinity),end=selected.reduce((max,f)=>Math.max(max,f),-Infinity);
 if(!Number.isFinite(start)||!Number.isFinite(end))throw Error('原草稿缺少来源范围，无法重新生成');
 previous.regenerating=true;
 let generated;
 try{
  generated=await summarize(start,end,previous.temporary,parents,previous.level,previous.hideAfter,previous.sources,{previous,instruction});
 }finally{delete previous.regenerating;}
 if(!generated)return;
 if(chatKey()!==origin||draft!==previous)throw Error('聊天或草稿已改变，新版本未替换原稿');
 if(previous.savedReview){
  generated.items=mapReviewedRewrite(previous.items,generated.items);
  generated.savedReview=true;
 }
 generated.batchOrdinal=previous.batchOrdinal;
 if(previous.batchOrdinal&&previous.items.every(m=>m.kind===previous.items[0].kind))generated.items.forEach(m=>m.kind=previous.items[0].kind);
 generated.rewritten=true;
 generated.reviewHistory=review?{...review,issues:normalizeIssues(review.issues||[],generated.items)}:null;
 const index=draftVersions.findIndex(v=>v.versionId===previous.versionId);
 if(index===-1)draftVersions.push(structuredClone(previous));
 else draftVersions[index]=structuredClone(previous);
 draft=generated;
 draftVersions.push(structuredClone(generated));
 clearSelections();
 const comparison=compareMemories(previous.items,generated.items);
 await log('按意见重写对比',comparison);
 tab='draft';
 open();
 notify(comparison.changed?'已生成新版本；旧版保留，可切换核对':'本次重写正文未发生变化；旧版保留');
}

